<script setup lang="ts">
/**
 * Register Page
 *
 * Registration form connected to the backend JWT auth.
 * Generated by Blacksmith. You own this file — customize as needed.
 */
import { reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import type { FormSubmitEvent } from '@nuxt/ui'
import type { z } from 'zod'
import UButton from '@nuxt/ui/components/Button.vue'
import UForm from '@nuxt/ui/components/Form.vue'
import UFormField from '@nuxt/ui/components/FormField.vue'
import UInput from '@nuxt/ui/components/Input.vue'
import { Path } from '@/router/paths'
import TextLink from '@/shared/components/TextLink.vue'
import { useAuth } from '../composables/use-auth'
import { registerSchema } from '../schemas'
import AuthPanel from '../components/AuthPanel.vue'

const router = useRouter()
const { register, error } = useAuth()

const state = reactive({ displayName: '', email: '', password: '' })
const submitting = ref(false)

async function onSubmit(event: FormSubmitEvent<z.output<typeof registerSchema>>) {
  submitting.value = true
  try {
    const { email, password, displayName } = event.data
    const result = await register(email, password, displayName)
    if (result.success) {
      await router.replace(Path.Home)
    }
  } finally {
    submitting.value = false
  }
}
</script>

<template>
  <AuthPanel title="Create your account" description="Sign up to get started." :error="error?.message">
    <UForm
      :schema="registerSchema"
      :state="state"
      class="flex flex-col gap-4"
      @submit="onSubmit"
    >
      <UFormField label="Name" name="displayName">
        <UInput
          v-model="state.displayName"
          autocomplete="name"
          placeholder="Your name"
          size="lg"
          class="w-full"
        />
      </UFormField>

      <UFormField label="Email address" name="email" required>
        <UInput
          v-model="state.email"
          type="email"
          autocomplete="email"
          placeholder="you@example.com"
          size="lg"
          class="w-full"
        />
      </UFormField>

      <UFormField label="Password" name="password" required>
        <UInput
          v-model="state.password"
          type="password"
          autocomplete="new-password"
          placeholder="Choose a password"
          size="lg"
          class="w-full"
        />
      </UFormField>

      <UButton
        type="submit"
        size="lg"
        block
        :loading="submitting"
        class="mt-2"
      >
        Create account
      </UButton>
    </UForm>

    <template #footer>
      <p>
        Already have an account?
        <TextLink :to="Path.Login">
          Log in
        </TextLink>
      </p>
    </template>
  </AuthPanel>
</template>
